package net.civeira.phylax.feature.observe.observeddashboard.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observeddashboard.domain.ObservedDashboardRefreshOptions;

class RefreshVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property refresh of observed dashboard ")
  void test_refresh_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> RefreshVO.tryFrom("_MANUAL_"));
    Assertions.assertEquals(ObservedDashboardRefreshOptions.MANUAL,
        RefreshVO.tryFrom("MANUAL").getRefresh());
    Assertions.assertThrows(ConstraintException.class, () -> RefreshVO.tryFrom(null));
    Assertions.assertEquals(ObservedDashboardRefreshOptions.MANUAL,
        RefreshVO.from(ObservedDashboardRefreshOptions.MANUAL).getRefresh());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> RefreshVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedDashboardRefreshOptions.MANUAL + "]",
        RefreshVO.from(ObservedDashboardRefreshOptions.MANUAL).toString());
  }
}
